package com.orangemask;import com.orangemask.dto.OrderDTO;import com.orangemask.service.OrderService;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Service;@Servicepublic class OrderConsumer{    private final OrderService orderService;    public OrderConsumer(OrderService orderService){        this.orderService = orderService;    }    @KafkaListener(topics = "auto-orders" , groupId = "T-DealerShip")    public void listen(String message){        String[] parts = message.split(":");        if(parts.length < 3){            return;        }        String carName = parts[0];        int carPrice = Integer.parseInt(parts[1]);        int downPaymentAmount = Integer.parseInt(parts[2]);    }    public OrderDTO parseMessage(String message){        String[] parts = message.split(":");        if(parts.length < 3){            throw new IllegalArgumentException("Invalid message format");        }        String carName = parts[0];        int carPrice = Integer.parseInt(parts[1]);        int downPaymentAmount = Integer.parseInt(parts[2]);        return new OrderDTO(carName,carPrice,downPaymentAmount);    }}